### **Terraform Modules for Hybrid Inventory Architecture**

#### **1. Core Infrastructure Module**
```hcl
module "global_inventory_infrastructure" {
  source  = "git::https://github.com/org/modules.git//inventory-platform"

  # Global Configuration
  regions = ["us-east-1", "eu-west-1", "ap-southeast-1"]

  # DynamoDB Configuration
  dynamodb_config = {
    table_name        = "GlobalInventory"
    billing_mode     = "PAY_PER_REQUEST"
    stream_enabled   = true

    global_secondary_indexes = [
      {
        name            = "ProductCategoryIndex"
        hash_key       = "product_category"
        projection_type = "ALL"
      }
    ]
  }

  # Kubernetes Cluster Specs
  kubernetes_cluster = {
    node_instance_type = "c5.2xlarge"
    min_nodes         = 3
    max_nodes         = 15
    autoscaling_mode  = "cluster-proportional"
  }
}
```

#### **2. Lambda Function Module**
```hcl
module "inventory_lambda_functions" {
  source = "terraform-aws-modules/lambda/aws"

  function_name = "inventory-read-resolver"
  handler       = "index.handler"
  runtime       = "python3.9"

  # Performance Optimization
  provisioned_concurrent_executions = 100
  memory_size                       = 1024
  timeout                           = 10

  # IAM & Security
  attach_policy_statements = true
  policy_statements = {
    dynamodb_read = {
      effect    = "Allow"
      actions   = ["dynamodb:GetItem", "dynamodb:Query"]
      resources = [module.global_inventory_infrastructure.dynamodb_arn]
    }
  }

  # Tracing & Monitoring
  tracing_mode = "Active"

  # Environment Configuration
  environment_variables = {
    CACHE_ENDPOINT = module.global_inventory_infrastructure.dax_endpoint
    REGION         = "us-east-1"
  }
}
```

#### **3. Advanced Networking Module**
```hcl
module "global_network_routing" {
  source  = "terraform-aws-modules/global-accelerator/aws"

  name    = "inventory-global-router"

  # Endpoint Configuration
  endpoints = [
    {
      region     = "us-east-1"
      weight     = 100
      health_check_protocol = "TCP"
      health_check_port     = 443
    },
    {
      region     = "eu-west-1"
      weight     = 50  # Lower priority
      health_check_protocol = "TCP"
      health_check_port     = 443
    }
  ]

  # Advanced Routing Rules
  routing_policy = {
    type = "WEIGHTED"
    latency_based_routing = true
  }
}
```

#### **4. Chaos Engineering Module**
```hcl
module "chaos_testing" {
  source = "github.com/chaos-toolkit/terraform-chaos"

  # Experiment Definitions
  experiments = [
    {
      name        = "network-partition-test"
      target_type = "dynamodb"
      blast_radius = 0.3  # 30% of infrastructure

      failure_modes = [
        {
          type   = "network_latency"
          params = {
            delay_ms     = 5000
            jitter_ms    = 1000
            probability  = 0.1
          }
        }
      ]
    },
    {
      name        = "lambda-cold-start-simulation"
      target_type = "lambda"

      failure_modes = [
        {
          type   = "resource_constraint"
          params = {
            cpu_limit    = "256m"
            memory_limit = "512Mi"
          }
        }
      ]
    }
  ]
}
```

### **Monitoring & Observability Integration**
```hcl
